'use strict';
(()=>{
const pdf='admission-plan-2027.pdf';
const source=(page,label='전형계획에서 확인')=>external(`${pdf}#page=${page}`,`${label} · ${page}쪽`,'plan-source');
const previousGuide=guideView;
guideView=function(){let box=document.createElement('div');box.innerHTML=previousGuide();let page=box.querySelector('.page');
let checklist=document.createElement('section');checklist.className='panel application-checklist';checklist.innerHTML=`<h2>원서 내기 전, 꼭 확인하세요</h2><ol><li><b>학교에서 정한 제출일 확인</b><p>공식 접수는 12월 4일~10일, 매일 09:00~17:00예요. 재학생은 담임 선생님의 안내에 따라 준비하세요. 학교 제출 마감일은 더 빠를 수 있어요.</p></li><li><b>마감 뒤에는 접수 취소 불가</b><p>12월 10일 오후 5시까지 온라인 전송과 종이 원서 제출이 모두 끝나야 해요. 온라인 원서가 승인돼야 접수가 완료됩니다.</p></li><li><b>원서의 지망 순서와 전화번호 확인</b><p>출력한 원서의 순서를 확인하고 학생·보호자 연락처도 확인하세요. 배정학교는 학생 휴대전화 문자로도 안내됩니다.</p></li></ol><p class="plan-facts">전형료 없음 · 재학생 원서 작성은 중학교에서 진행</p><p>${source(8,'접수 기간·취소 기준')} · ${source(37,'최종 확인 사항')}</p>`;
page.querySelector('.intro').after(checklist);
let timeline=box.querySelector('.timeline');if(timeline){let note=timeline.parentElement.querySelector('.hint');if(note){note.textContent='2026년 10월 신입생 전형계획 31~32쪽 기준입니다. 일정이 바뀔 수 있으니 학교의 최신 안내를 확인하세요.';note.insertAdjacentHTML('afterend',source(32,'일정 원본'))}let sections=[...timeline.children],register=sections.find(s=>s.textContent.includes('배정 학교 등록'));if(register){let meetup=document.createElement('section');meetup.innerHTML='<small>2027. 1. 25. 오전 10시</small><b>등록 안내 예비소집</b><p>배정받은 학교에서 안내해요. 학교에 따라 일정·방법이 달라질 수 있으니 학교 공지를 먼저 확인하세요.</p>';register.before(meetup)}let announcement=sections.find(s=>s.textContent.includes('배정 학교 발표'));if(announcement)announcement.insertAdjacentHTML('beforeend','<p>학교·교육지원청 또는 SATP에서 확인할 수 있어요. 학생 휴대전화로도 안내됩니다.</p>');}
let docs=box.querySelector('.doclist');if(docs)docs.insertAdjacentHTML('afterbegin',`<a class="doclink" href="${pdf}" target="_blank" rel="noopener">2027학년도 신입생 전형계획 <span>↗</span></a><a class="doclink" href="${pdf}#page=24" target="_blank" rel="noopener">부천 22개교 공식 모집정원 · 24쪽 <span>↗</span></a>`);
let extra=document.createElement('section');extra.className='panel application-extra';let m=origin(),submission=m?.applicationSubmission;
extra.innerHTML=`<h2>접수 방법·문의</h2><p>부천 중학교 재학생은 학교에서 원서를 작성해요. 검정고시 합격자 등은 필요한 서류를 갖춰 부천교육지원청에 방문해 접수합니다.</p><div class="plan-contacts"><a href="tel:0326200178">부천교육지원청 032-620-0178</a><a href="tel:0326200179">032-620-0179</a>${external('https://satp.goe.go.kr','입학·전학 포털(SATP)')}</div><small>${source(9,'접수처·문의')}</small>${submission?`<details class="plan-details"><summary>${esc(m.name)} 교육지원청 제출 일정</summary><p><b>12월 ${Number(submission.date.slice(-2))}일 ${submission.period}</b></p><p>중학교에서 교육지원청으로 원서를 내는 일정이에요. 학생이 학교에 내는 마감일과 다르므로 담임 선생님의 안내를 따라 주세요.</p>${source(12,'학교별 제출 일정')}</details>`:''}<details class="plan-details"><summary>서류와 사진 준비</summary><p>최근 6개월 이내 촬영한 3×4cm 상반신 사진을 사용하며, 재학생은 학교생활기록부의 사진이 반영됩니다. 검정고시 합격자는 합격·성적증명서, 30KB 이하 사진 파일, 주민등록등본(상세발급) 등이 필요해요. 졸업자·타 시도 출신자 등은 추가 서류를 확인하세요.</p>${source(15,'제출서류')} · ${source(35,'작성·제출 방법')}</details><details class="plan-details"><summary>별도 신청이 필요한 경우</summary><ul><li><b>체육특기자·특수교육대상자</b>: 체육특기자로 인정돼도 입학원서는 반드시 제출해야 해요. 특수교육대상자는 별도 심의·배치 절차를 따르며 일반고 응시원서를 따로 제출하지 않습니다. ${source(9)} · ${source(18)}</li><li><b>지체장애·일부 질환에 따른 선배정</b>: 심사 대상에 해당하면 11월 11일 오후 5시까지 중학교에 신청합니다. 승인받아도 일반고 입학원서는 별도로 제출해야 해요. 대상·증빙서류는 학교와 확인하세요. ${source(18)}</li><li><b>특례입학</b>: 지원 고등학교에 직접 신청합니다. 11월 26일~12월 2일은 권장 일정이므로 해당 학교의 전형일정을 확인하세요. ${source(19)}</li><li><b>쌍둥이 동일교 배정</b>: 각각 지원서를 내고 맏이와 지망 순서를 같게 작성합니다. 남녀 쌍둥이는 여고를 끝지망에 쓰는 등 별도 조건이 있어요. ${source(19)}</li><li><b>교직원 자녀 타교 배정·학교폭력 관련 분리배정</b>: 희망·대상 조건과 서류를 담임 선생님에게 미리 문의하세요. ${source(20)}</li></ul></details><details class="plan-details"><summary>동시지원·추가배정 유의사항</summary><p>외고·국제고·자사고와 동시지원하면 해당 학교를 1지망으로, 부천 일반고 전체를 2지망부터 적습니다. 일반고 원서도 별도로 제출해야 해요. 이 앱의 지망표는 일반고 사이의 순서를 정리하는 참고용입니다.</p><p>평준화 일반고는 별도 추가모집이 없습니다. 미등록 결원에 따른 차순위자 추가배정 발표는 2027년 2월 4일, 등록은 2월 4~5일입니다. 합격·배정된 뒤 등록을 포기해도 다른 학교의 추가모집에 지원할 수 없어요.</p>${source(35,'동시지원 지망 작성')} · ${source(36,'이중지원·추가모집 제한')} · ${source(32,'추가배정 일정')}</details>`;
page.querySelector('.panels').after(extra);return box.innerHTML;};
const previousDetail=renderDetail;
renderDetail=function(){previousDetail();if(detailTab!=='overview')return;let s=school(detailSchool);if(!s.quotaSource)return;let detail=document.createElement('details');detail.className='plan-details quota-plan';detail.innerHTML=`<summary>공식 모집정원 확인</summary><p>2027학년도 ${s.classes2027}학급 · ${s.quota}명 모집</p>${s.athletes2027?`<p>체육특기자 계획: ${esc(s.athletes2027.sport)} ${s.athletes2027.planned}명. 체육특기자는 정원 내 선배정이며, 일반 지원자의 실제 배정 인원과는 구분해야 해요.</p>`:''}<p class="hint">모집정원과 실제 배정 인원은 다를 수 있습니다. 배정 원칙은 지원 안내에서 확인해 주세요.</p>${source(24,'부천 학교별 모집 현황')}`;$('#detailBody').append(detail);};
if(data){render();renderSim();}
})();
